import {Shift,TYPES,ORDER,lifeStep,threatCells} from './engine.mjs';
const $=s=>document.querySelector(s);let shift=new Shift(),filter=null,selectedId=null,last=performance.now(),lifeGen=-1,stampUntil=0,reported=false,guideResume=false;const width=38,height=18,boards={};let boardTick=0;let atlasLife=new Set(),timelineItems=[],lastTimeline="";
function initBoards(){atlasLife=new Set();for(let y=1;y<59;y++)for(let x=1;x<95;x++)if((x*17+y*31+x*y*3)%19<4)atlasLife.add(y*96+x);lifeGen=-1;}
$('#zones').innerHTML=ORDER.map((type,i)=>`<article class="zone" id="zone-${type}"><button class="zonepick" data-select="${type}" aria-label="${TYPES[type].name}の伝票を調べる"><span><b>${['⌑ 本人確認','▤ 共有領域','⇥ 外部からの入口','▣ データ出口'][i]}</b><small>${TYPES[type].pattern}</small></span><span class="zonestatus" id="status-${type}">監視中</span></button><div class="zonefoot"><p id="hint-${type}"></p><button class="patch" data-patch="${type}" disabled></button></div></article>`).join('');
initBoards();
$('#mainboard').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();const x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;selectZone(ORDER[(y>.5?2:0)+(x>.5?1:0)]);};
function selectZone(type){filter=type;selectedId=null;stampUntil=0;renderUI(true);if(matchMedia('(max-width:720px)').matches)setView('desk');}
function setView(view){document.body.dataset.view=view;$('#showBoard').setAttribute('aria-pressed',String(view==='board'));$('#showDesk').setAttribute('aria-pressed',String(view==='desk'));}
function getRequest(){return shift.pending(filter).find(r=>r.id===selectedId)||null;}
function renderPaper(r){const t=TYPES[r.type],labels=r.type==='auth'?['本人','鍵の送信先']:r.type==='share'?['持ち主','閲覧者']:r.type==='flood'?['送信者','毎秒の件数']:['資料の種類','送り先'];$('#paper').innerHTML=`<div class="paperhead"><span>通信審査局 / TRANSIT FORM</span><span>#${String(r.id).padStart(3,'0')}</span></div><h3>${r.type==='exfil'?'送信申請書':r.type==='flood'?'受付申請書':r.type==='share'?'閲覧申請書':'再設定申請書'}</h3><div class="applicant"><div class="portrait" aria-hidden="true"><i></i></div><div><span>申請者 / APPLICANT</span><b>${r.type==='exfil'?'データ転送担当':r.a}</b><small>${t.name} / NETWORK TRANSIT</small><div class="barcode">▎▍▏▎▍▍▏▎▏▍▎▍</div></div></div><p class="papertype">${t.name} · ${r.type==='exfil'?'OUTBOUND / 外へ出る通信':'INBOUND / 内へ入る通信'}</p><div class="paperrow"><span>${labels[0]}</span><strong class="${r.type==='exfil'?'jp':''}">${r.a}</strong></div><div class="paperrow"><span>${labels[1]}</span><strong class="${r.type==='exfil'?'jp':''}">${r.b}${r.type==='flood'?' 件':''}</strong></div><div class="rule"><b>通過条件</b><br>${t.rule}</div><div class="deadline"><span>AUTO PASS IN</span><b id="deadline">${Math.max(0,Math.ceil(r.deadline-shift.time))}s</b></div>`;$('#paper').hidden=false;$('#empty').hidden=true;}
function renderUI(force=false){const pending=shift.pending(filter);if(!pending.some(r=>r.id===selectedId)){selectedId=pending[0]?.id??null;force=true;}const r=getRequest();$('#clock').textContent=format(120-shift.time);$('#eventTime').textContent=format(shift.time);$('#integrity').textContent=shift.data;$('#trust').textContent=shift.trust;$('#dataMeter').style.width=shift.data+'%';$('#trustMeter').style.width=shift.trust+'%';$('#pending').textContent=String(shift.pending().length).padStart(2,'0');$('#mobileCount').textContent=shift.pending().length;$('#fixed').textContent=shift.repaired;$('#deskCount').textContent=String(pending.length).padStart(2,'0')+' WAITING';$('#filterLabel').textContent=filter?TYPES[filter].name+' の伝票':'すべての領域';$('#eventLog').textContent=shift.lastLog;$('#startBtn').hidden=shift.started;$('#pauseBtn').hidden=!shift.started;$('#pauseBtn').disabled=shift.done;$('#pauseBtn').textContent=shift.running?'一時停止 Ⅱ':'再開 ▶';const busy=ORDER.find(k=>shift.zones[k].repairEnd);$('#worker').textContent=busy?TYPES[busy].name+'：あと'+Math.ceil(shift.zones[busy].repairEnd-shift.time)+'秒':'修正担当：待機中';
const q=pending.map(x=>`<button class="queueitem ${x.id===selectedId?'selected':''} ${x.deadline-shift.time<5?'urgent':''}" data-ticket="${x.id}" aria-label="伝票 ${x.id} ${TYPES[x.type].name}">#${String(x.id).padStart(3,'0')}</button>`).join('');if($('#queue').innerHTML!==q)$('#queue').innerHTML=q;
if(r){if(force||$('#paper').dataset.ticket!==String(r.id)){renderPaper(r);$('#paper').dataset.ticket=r.id;}if($('#deadline'))$('#deadline').textContent=Math.max(0,Math.ceil(r.deadline-shift.time))+'s';}else{$('#paper').hidden=true;$('#paper').dataset.ticket='';$('#empty').hidden=false;$('#empty').innerHTML=shift.started?'<div>▤</div><h3>この領域の伝票は、審査済み。</h3><p>次の通信を待つか、<br>「全伝票を表示」で別の領域へ。</p><span>静かな間に根本修正もできます。</span>':'<div>▤</div><h3>最初の伝票を、待っている。</h3><p>当直を開始すると通信が届きます。<br>二つの欄を照合して、通すか止めるか。</p><span>判定はすぐ、左の盤面へ返ります。</span>';}
$('#allowBtn').disabled=$('#denyBtn').disabled=!shift.running||!r||performance.now()<stampUntil;
for(const type of ORDER){const z=shift.zones[type],n=shift.pending(type).length;$('#zone-'+type).classList.toggle('selected',filter===type||(!filter&&r?.type===type));$('#zone-'+type).classList.toggle('underattack',z.attacks>0);$('#zone-'+type).classList.toggle('fixed',z.fixed);$('#status-'+type).textContent=!shift.started?'パターン見本':z.fixed?'▥ 防壁稼働':z.repairEnd?'修正中 '+Math.ceil(z.repairEnd-shift.time)+'s':z.attacks?'侵入 '+z.attacks+'件':n?'審査待ち '+n+'件':'● 正常';$('#hint-'+type).textContent=z.fixed?'青い防壁が再侵入を防ぐ。':z.attacks?TYPES[type].label+'が進行中。修正で止める。':TYPES[type].hint;const p=$('[data-patch="'+type+'"]');p.disabled=!shift.running||z.fixed||!!busy;p.textContent=z.fixed?'▥ 修正済み':z.repairEnd?'修正中… '+Math.ceil(z.repairEnd-shift.time)+'s':'▥ 根本修正 · 10秒';}
renderTelemetry();if(shift.done&&!reported){reported=true;showReport();}}
function format(t){const s=Math.max(0,Math.ceil(t));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function decide(allow){if(performance.now()<stampUntil)return;const r=getRequest();if(!r||!shift.decide(r.id,allow))return;$('#stamp').textContent=allow?'APPROVED':'DENIED';$('#stamp').className='stamp show '+(allow?'approved':'denied');stampUntil=performance.now()+650;selectedId=null;renderUI(true);}
function drawCell(ctx,x,y,color,outline=false){if(x<0||x>=width||y<0||y>=height)return;ctx.fillStyle=color;if(outline){ctx.strokeStyle=color;ctx.setLineDash([3,3]);ctx.strokeRect(x*20+3,y*20+3,14,14);ctx.setLineDash([]);}else ctx.fillRect(x*20+3,y*20+3,14,14);}
const ORIGINS={auth:[3,4],share:[51,4],flood:[3,35],exfil:[51,35]};
function drawBoards(now){const visualTime=shift.started?shift.time:now/1000;const gen=Math.floor(visualTime*3),ctx=$('#mainboard').getContext('2d');if(gen!==lifeGen){atlasLife=lifeStep(atlasLife,96,60);if(gen%9===0)for(let j=0;j<8;j++){const x=4+(gen*3+j*13)%83,y=3+(gen+j*7)%49;for(const[dx,dy]of[[1,0],[2,1],[0,2],[1,2],[2,2]])atlasLife.add((y+dy)*96+x+dx);}lifeGen=gen;}$('#generation').textContent='世代 '+String(gen).padStart(4,'0');ctx.fillStyle='#091713';ctx.fillRect(0,0,1152,720);
const cell=(x,y,color,glow=false,outline=false)=>{if(x<0||x>=96||y<0||y>=60)return;ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=glow?9:0;if(outline){ctx.strokeStyle=color;ctx.setLineDash([2,2]);ctx.strokeRect(x*12+1,y*12+1,9,9);ctx.setLineDash([]);}else ctx.fillRect(x*12+1,y*12+1,9,9);ctx.shadowBlur=0;};
for(let y=0;y<60;y++)for(let x=0;x<96;x++)cell(x,y,(x+y)%3?'#12271f':'#183024');for(const n of atlasLife)cell(n%96,Math.floor(n/96),(n+gen)%7===0?'#8ec765':'#3b6e3a',(n+gen)%11===0);
for(const type of ORDER){const z=shift.zones[type],[ox,oy]=ORIGINS[type];const paint=(age,seed,preview=false)=>{for(const[x,y]of threatCells(type,age,seed)){if(!z.fixed)cell(ox+x,oy+y,preview?'#c9a34d':'#ed6753',true);else if(type==='exfil'?x>=20:x<=16)cell(ox+x,oy+y,'#dd7257',true);}};if(!shift.started)paint(visualTime%14,ORDER.indexOf(type),true);else{for(const r of shift.pending(type))for(const[x,y]of threatCells(type,Math.min((shift.time-r.at)*.25,3),r.id).slice(0,12))cell(ox+x,oy+y,'#e6b665',false,true);for(const r of shift.requests.filter(r=>r.type===type&&!r.valid&&['allow','timeout'].includes(r.status)))paint(shift.time-(r.decisionAt??r.at),r.id);for(const e of shift.effects.filter(e=>e.type===type&&shift.time-e.at<5)){const age=shift.time-e.at;if(e.kind==='good')for(let k=0;k<6;k++)cell(ox+2+(Math.floor(age*6)+k)%34,oy+9,'#c0f298',true);if(e.kind==='stop'||e.kind==='falseblock')for(let k=0;k<5;k++)cell(ox+4+k,oy+8+k%2,e.kind==='stop'?'#89bfda':'#c59a62',true);}}
if(z.fixed){for(let y=0;y<22;y++){cell(ox+18,oy+y,'#7ebac8');cell(ox+19,oy+y,'#325564');}for(let y=5;y<18;y+=5)cell(ox+(type==='exfil'?20:17),oy+y,'#f4b079',true);}else if(z.repairEnd){for(let y=0;y<Math.floor((1-(z.repairEnd-shift.time)/10)*22);y++)cell(ox+18,oy+y,'#80b9c6',false,true);}
if(z.quarantineUntil>shift.time){ctx.fillStyle='#0b2519aa';ctx.fillRect((ox-1)*12,(oy-1)*12,42*12,24*12);ctx.strokeStyle='#b89b51';ctx.setLineDash([8,5]);ctx.strokeRect((ox-1)*12,(oy-1)*12,42*12,24*12);ctx.setLineDash([]);ctx.fillStyle='#d3ba80';ctx.font='18px monospace';ctx.fillText('QUARANTINED', (ox+6)*12,(oy+13)*12);}
if(filter===type){ctx.strokeStyle='#d3ddbb88';ctx.lineWidth=1;ctx.setLineDash([6,9]);ctx.strokeRect((ox-1)*12,(oy-1)*12,42*12,24*12);ctx.setLineDash([]);}}
// Crosshair and small monitoring beacons live on the same uninterrupted grid.
for(const[x,y]of[[14,25],[47,13],[73,30],[29,49]]){ctx.strokeStyle='#9acb74';ctx.strokeRect(x*12,y*12,24,24);cell(x+1,y+1,'#c4f0a2',true);}const r=getRequest();if(r){const[ox,oy]=ORIGINS[r.type];ctx.strokeStyle='#efe4c3';ctx.lineWidth=2;const x=(ox+25)*12,y=(oy+9)*12;for(const[dx,dy]of[[-1,-1],[1,-1],[-1,1],[1,1]]){ctx.beginPath();ctx.moveTo(x+dx*18,y+dy*8);ctx.lineTo(x+dx*18,y+dy*18);ctx.lineTo(x+dx*8,y+dy*18);ctx.stroke();}}
}
function renderTelemetry(){const attacks=ORDER.reduce((n,k)=>n+shift.zones[k].attacks,0);$('#threatBars').innerHTML=Array.from({length:12},(_,i)=>'<i class="'+(i<Math.min(12,attacks*3)?'lit':'')+'"></i>').join('');$('#threatLabel').textContent=!shift.started?'待機':attacks>=3?'高':attacks?'中':'低';$('#threatLabel').style.color=attacks?'#ef785d':'#9dca83';$('#dataValue').textContent=shift.data+'%';$('#trustValue').textContent=shift.trust+'%';$('#queueMeter').style.width=Math.min(100,shift.pending().length*25)+'%';$('#mapMode').textContent=!shift.started?'パターン見本 / 当直開始で審査':shift.running?'実時間で進行中':'一時停止中';const type=filter||getRequest()?.type||'auth';const z=shift.zones[type],busy=ORDER.some(k=>shift.zones[k].repairEnd);$('#rootFixBtn').disabled=!shift.running||z.fixed||busy;$('#rootFixBtn').title=TYPES[type].name+'：'+TYPES[type].patch;$('#quarantineBtn').disabled=!shift.running||shift.quarantineUses>=2||z.quarantineUntil>shift.time||z.fixed;$('#inspectBtn').disabled=!shift.started;$('#mapHint').textContent=TYPES[type].name+'：'+TYPES[type].hint;
if(shift.lastLog!==lastTimeline){lastTimeline=shift.lastLog;timelineItems.unshift({at:format(shift.time),text:shift.lastLog});timelineItems=timelineItems.slice(0,7);$('#timeline').innerHTML=timelineItems.map(e=>'<div><time>'+e.at+'</time><p>'+e.text+'</p></div>').join('');}
const pending=ORDER.filter(k=>shift.zones[k].attacks||shift.pending(k).length);$('#incidentCount').textContent=pending.length;$('#incidents').innerHTML=pending.length?pending.map(k=>'<button data-incident="'+k+'" class="'+(shift.zones[k].attacks?'hot':'')+'"><span>△</span><div><b>'+TYPES[k].name+'</b><small>'+(shift.zones[k].attacks?TYPES[k].label+'が進行中':shift.pending(k).length+'件の申請が審査待ち')+'</small></div><i>↗</i></button>').join(''):'<p class="noincident">現在、未対応の異常なし。</p>';}
function showReport(){$('#reportTitle').textContent=shift.data>=85&&shift.trust>=85?'守ったのは、データと信頼。':shift.data>=60?'当直終了。次は、もっと守れる。':'赤い侵食が、抜け道を広げた。';$('#reportMetrics').innerHTML=`<div><strong>${shift.data}%</strong><small>守ったデータ</small></div><div><strong>${shift.trust}%</strong><small>利用者の信頼</small></div><div><strong>${shift.repaired}/4</strong><small>根本修正</small></div>`;$('#reportZones').innerHTML=ORDER.map(type=>{const z=shift.zones[type];return `<div class="reportzone"><b>${TYPES[type].name} / ${TYPES[type].label}　${z.fixed?'▥ 修正済み':'未修正'}</b><p>正しい審査 ${z.correct}件 · 不正通過 ${z.missed}件 · 防壁の自動拒否 ${z.defended}件 · 未審査 ${shift.pending(type).length}件</p><p>守る仕組み：${TYPES[type].patch}。</p></div>`;}).join('');$('#report').showModal();}
function reset(){shift=new Shift();selectedId=null;filter=null;reported=false;stampUntil=0;timelineItems=[];lastTimeline='';$('#memo').textContent='盤面と伝票を照合し、広がる前に対応する。';$('#stamp').className='stamp';$('#report').close();initBoards();setView('board');renderUI(true);}
$('#startBtn').onclick=()=>{shift.start();filter=null;last=performance.now();renderUI(true)};$('#pauseBtn').onclick=()=>{if(shift.done)return;shift.running=!shift.running;last=performance.now();renderUI()};$('#zones').onclick=e=>{const patch=e.target.closest('[data-patch]'),pick=e.target.closest('[data-select]');if(patch){shift.repair(patch.dataset.patch);renderUI();}else if(pick)selectZone(pick.dataset.select)};$('#queue').onclick=e=>{const b=e.target.closest('[data-ticket]');if(b){selectedId=Number(b.dataset.ticket);stampUntil=0;renderUI(true)}};$('#allBtn').onclick=()=>{filter=null;selectedId=null;renderUI(true)};$('#allowBtn').onclick=()=>decide(true);$('#denyBtn').onclick=()=>decide(false);$('#resetBtn').onclick=reset;$('#retryBtn').onclick=reset;$('#closeReport').onclick=()=>$('#report').close();$('#guideBtn').onclick=()=>{guideResume=shift.running;shift.running=false;$('#guide').showModal();renderUI()};function closeGuide(){$('#guide').close();if(guideResume&&!shift.done)shift.running=true;guideResume=false;last=performance.now();renderUI()}$('#closeGuide').onclick=closeGuide;$('#guideStart').onclick=closeGuide;$('#guide').addEventListener('cancel',e=>{e.preventDefault();closeGuide()});$('#showBoard').onclick=()=>setView('board');$('#showDesk').onclick=()=>setView('desk');document.addEventListener('keydown',e=>{if(e.repeat||$('#guide').open||$('#report').open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();decide(false)}else if(e.key==='ArrowRight'){e.preventDefault();decide(true)}});
$('#inspectBtn').onclick=()=>{const r=getRequest(),type=filter||r?.type||'auth';$('#memo').textContent=TYPES[type].rule+' '+TYPES[type].hint;document.querySelectorAll('.checksheet input').forEach(x=>x.checked=false);if(matchMedia('(max-width:720px)').matches)setView('desk');};$('#rootFixBtn').onclick=()=>{shift.repair(filter||getRequest()?.type||'auth');renderUI()};$('#quarantineBtn').onclick=()=>{shift.quarantine(filter||getRequest()?.type||'auth');renderUI()};$('#incidents').onclick=e=>{const b=e.target.closest('[data-incident]');if(b)selectZone(b.dataset.incident)};let uiTick=0;function frame(now){const dt=Math.min(.5,(now-last)/1000);last=now;if(shift.running)shift.advance(dt);if(now-uiTick>150){if(now>=stampUntil)$('#stamp').classList.remove('show');renderUI();drawBoards(now);uiTick=now;}requestAnimationFrame(frame);}renderUI(true);requestAnimationFrame(frame);
